namespace sv_d9498aab38a740b3b4c3e989022f0d2c.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = "warehouse-a";
    public string Name { get; set; } = "Warehouse A";
}

public class WarehouseState
{
    private WarehouseInfo _current = new();

    public WarehouseInfo Current => _current;

    public event Action? OnChange;

    public static readonly List<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "warehouse-a", Name = "Warehouse A" },
        new() { Id = "warehouse-b", Name = "Warehouse B" },
        new() { Id = "warehouse-c", Name = "Warehouse C" }
    ];

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = AvailableWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse is not null && warehouse.Id != _current.Id)
        {
            _current = warehouse;
            OnChange?.Invoke();
        }
    }
}

namespace sv_d9498aab38a740b3b4c3e989022f0d2c.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all
/// subscribed components when new data arrives. Each circuit (user session)
/// gets its own instance, ensuring independent state per user.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired from a background thread when polling detects new data.
    /// Subscribers must wrap StateHasChanged in InvokeAsync.
    /// </summary>
    public event Func<Task>? OnAlertUpdated;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component becomes visible and wants polling to run.
    /// Polling starts on the first subscriber and stops when all unsubscribe.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    /// <summary>
    /// Call when a component is disposed or leaves visibility.
    /// </summary>
    public void Unsubscribe()
    {
        _subscriberCount--;
        if (_subscriberCount <= 0)
        {
            _subscriberCount = 0;
            StopPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
        _cts?.Dispose();
        _cts = null;
    }

    private async Task PollLoopAsync(CancellationToken cancellationToken)
    {
        // Immediately fetch on start
        await FetchAndNotifyAsync();

        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                if (await _timer!.WaitForNextTickAsync(cancellationToken))
                {
                    await FetchAndNotifyAsync();
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.Current.Id);
        if (OnAlertUpdated is not null)
        {
            await OnAlertUpdated.Invoke();
        }
    }

    public void Dispose()
    {
        StopPolling();
    }
}

