@page "/dashboard"
@rendermode InteractiveServer
@implements IDisposable
@inject sv_d9498aab38a740b3b4c3e989022f0d2c.Services.WarehouseState WarehouseState
@inject sv_d9498aab38a740b3b4c3e989022f0d2c.Services.InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-3">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@WarehouseState.Current.Name</p>
    </div>
</div>

<div class="card mb-3">
    <div class="card-body">
        <h5 class="card-title">Low Stock Alerts</h5>
        <p class="card-text">
            <span class="badge bg-danger fs-5">@AlertService.CurrentLowStockCount</span>
            <span class="ms-2 text-muted">items below minimum level</span>
        </p>
        <small class="text-muted">Auto-refreshes every 10 seconds</small>
    </div>
</div>

@code {
    private Func<Task>? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        // Subscribe to warehouse changes
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // Subscribe to alert updates and start polling
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertUpdated += _alertHandler;
        AlertService.Subscribe();
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _warehouseHandler;

        if (_alertHandler is not null)
        {
            AlertService.OnAlertUpdated -= _alertHandler;
        }

        AlertService.Unsubscribe();
    }
}

